CREATE FUNCTION public.organization_is_public(_organization_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.organizations WHERE id=_organization_id AND status IN ('active','suspended')) $$;
REVOKE ALL ON FUNCTION public.organization_is_public(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.organization_is_public(uuid) TO anon,authenticated,service_role;
CREATE FUNCTION public.tournament_is_public(_tournament_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.tournaments WHERE id=_tournament_id AND public.organization_is_public(organization_id)) $$;
REVOKE ALL ON FUNCTION public.tournament_is_public(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.tournament_is_public(uuid) TO anon,authenticated,service_role;
CREATE FUNCTION public.tournament_accepts_registration(_tournament_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.tournaments t JOIN public.organizations o ON o.id=t.organization_id WHERE t.id=_tournament_id AND t.status='open' AND o.status='active') $$;
REVOKE ALL ON FUNCTION public.tournament_accepts_registration(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.tournament_accepts_registration(uuid) TO authenticated,service_role;
ALTER POLICY "Anyone can read tournaments" ON public.tournaments USING (public.organization_is_public(organization_id));
ALTER POLICY "Admins can insert tournaments" ON public.tournaments WITH CHECK(public.can_manage_organization(organization_id));
ALTER POLICY "Admins can update tournaments" ON public.tournaments USING(public.can_manage_tournament(id)) WITH CHECK(public.can_manage_tournament(id));
ALTER POLICY "Admins can delete tournaments" ON public.tournaments USING(public.can_manage_organization(organization_id));
CREATE POLICY tournaments_manager_read ON public.tournaments FOR SELECT TO authenticated USING(public.can_manage_tournament(id));
ALTER POLICY "Anyone reads teams" ON public.tournament_teams USING(public.tournament_is_public(tournament_id));
ALTER POLICY "Captain or admin inserts team" ON public.tournament_teams WITH CHECK(public.can_manage_tournament(tournament_id) OR (captain_id=auth.uid() AND public.tournament_accepts_registration(tournament_id)));
ALTER POLICY "Captain or admin deletes team" ON public.tournament_teams USING(public.can_manage_tournament(tournament_id) OR (captain_id=auth.uid() AND public.tournament_accepts_registration(tournament_id)));
ALTER POLICY "Admin updates team" ON public.tournament_teams USING(public.can_manage_tournament(tournament_id)) WITH CHECK(public.can_manage_tournament(tournament_id));
CREATE POLICY teams_manager_read ON public.tournament_teams FOR SELECT TO authenticated USING(public.can_manage_tournament(tournament_id));
ALTER POLICY "Anyone reads matches" ON public.tournament_matches USING(public.tournament_is_public(tournament_id));
ALTER POLICY "Admin inserts matches" ON public.tournament_matches WITH CHECK(public.can_manage_tournament(tournament_id));
ALTER POLICY "Admin updates matches" ON public.tournament_matches USING(public.can_manage_tournament(tournament_id)) WITH CHECK(public.can_manage_tournament(tournament_id));
ALTER POLICY "Admin deletes matches" ON public.tournament_matches USING(public.can_manage_tournament(tournament_id));
CREATE POLICY matches_manager_read ON public.tournament_matches FOR SELECT TO authenticated USING(public.can_manage_tournament(tournament_id));
ALTER POLICY "Users can read their own registrations" ON public.registrations USING(user_id=auth.uid() OR public.can_manage_tournament(tournament_id));
ALTER POLICY "Users can cancel their own registration" ON public.registrations USING(public.can_manage_tournament(tournament_id) OR (user_id=auth.uid() AND public.tournament_accepts_registration(tournament_id)));
ALTER POLICY "Users can register themselves" ON public.registrations WITH CHECK(user_id=auth.uid() AND public.tournament_accepts_registration(tournament_id));
ALTER POLICY "Admins can update registrations" ON public.registrations USING(public.can_manage_tournament(tournament_id)) WITH CHECK(public.can_manage_tournament(tournament_id));
ALTER POLICY "Admins read helloasso regs" ON public.helloasso_registrations USING(public.can_manage_tournament(tournament_id));
ALTER POLICY "Admins delete helloasso regs" ON public.helloasso_registrations USING(public.can_manage_tournament(tournament_id));
ALTER POLICY "Anyone can read photos" ON public.photos USING(public.organization_is_public(organization_id));
ALTER POLICY "Admins can insert photos" ON public.photos WITH CHECK(public.can_manage_organization(organization_id));
ALTER POLICY "Admins can update photos" ON public.photos USING(public.can_manage_organization(organization_id)) WITH CHECK(public.can_manage_organization(organization_id));
ALTER POLICY "Admins can delete photos" ON public.photos USING(public.can_manage_organization(organization_id));
ALTER POLICY "Anyone can read standings" ON public.standings USING(public.organization_is_public(organization_id));
ALTER POLICY "Admins can insert standings" ON public.standings WITH CHECK(public.can_manage_organization(organization_id));
ALTER POLICY "Admins can update standings" ON public.standings USING(public.can_manage_organization(organization_id)) WITH CHECK(public.can_manage_organization(organization_id));
ALTER POLICY "Admins can delete standings" ON public.standings USING(public.can_manage_organization(organization_id));
ALTER POLICY "Anyone can read highlights" ON public.highlights USING(public.organization_is_public(organization_id));
ALTER POLICY "Admins can insert highlights" ON public.highlights WITH CHECK(public.can_manage_organization(organization_id));
ALTER POLICY "Admins can update highlights" ON public.highlights USING(public.can_manage_organization(organization_id)) WITH CHECK(public.can_manage_organization(organization_id));
ALTER POLICY "Admins can delete highlights" ON public.highlights USING(public.can_manage_organization(organization_id));
COMMENT ON TABLE public.user_roles IS 'DEPRECATED for tournament/content authorization: use organization_members and platform_roles. Legacy member administration and global statistics remain gated pending their separate cutover.';